seqs = {}
for name in ["input", "egfp", "flag", "snap"]:
    seqs[name] = open(name + ".fa").read().strip()

# Build a list of every 4 letter word that occurs in the parts to be used
bad = set()
for name in ["egfp", "flag", "snap"]:
    s = seqs[name]
    for k in range(len(s) - 3):
        bad.add(s[k:k + 4])

print("count of 4 letter words to avoid is %d" % len(bad))

# Now run through all possible 4 letter words to find ones not in that list
alphabet = "acgt"
free = []
for a in alphabet:
    for b in alphabet:
        for c in alphabet:
            for d in alphabet:
                w = a + b + c + d
                if w not in bad:
                    free.append(w)
print("the following words are available:")
for w in free:
    print("  " + w)
